drawQuad = ( size <= 0.0f ) ? 0.0f : 1.0f;
drawQuad = ( angle >= kCliffCullingAngle ) ? 0.0f : drawQuad;
drawQuad = ( height < seaLevel ) ? 0.0f : drawQuad;
