}
else
{
x0 = reflectedNormal;
}
float3 x1 = x0 * x0;
float3 x2 = x0 * x0.yzx;
if (!kSaveInstructions)
{
shColorSpec += shCoeffs[ 9].xyz * (3 * x1.x - x1.y) * x0.y;
shColorSpec += shCoeffs[10].xyz * x1.x * x0.z;
