shColorSpec += shCoeffs[11].xyz * (5 * x1.z - 1) * x0.y;
shColorSpec += shCoeffs[12].xyz * (5 * x1.z - 3) * x0.z;
shColorSpec += shCoeffs[13].xyz * (5 * x1.z - 1) * x0.x;
