triplanarNormal = lerp(triplanarNormal, forestNormal.xyz, forestAmount);
float gloss = 1.0f;
float specPow = 64.0 / 255.0;
Current.color.w = specPow;  
Current.color1 = float4(triplanarNormal * 0.5 + 0.5, gloss);
}

