// If the emissive mask falls below the epsilon value then clamp it to 0.
// Otherwise the overbrightened color values expose these errors.
 emissiveMask = ( emissiveMask < kEpsilon ) ? kZero : emissiveMask;

float3 emissiveColorA = kHeadlightColor * emissiveMask.x;
float3 emissiveColorB = kBrakeColor     * emissiveMask.y;
float3 emissiveColorC = kRunningColor   * emissiveMask.z;
finalColor += ( emissiveColorA + emissiveColorB + emissiveColorC );

ps.decl:
static const float3 kHeadlightColor = float3( 60.0f, 40.0f, 10.0f );
static const float3 kBrakeColor     = float3( 250.0f, 0.3f, 0.3f );
static const float3 kRunningColor   = float3( 1.75f, 0.25f, 0.25f );
static const float3 kEpsilon = float3( 0.05f, 0.05f, 0.05f );
static const float3 kZero    = float3( 0.0f, 0.0f, 0.0f );

ps.main:
// Calculate interior colour.
float2 interiorUv    = uv1;
float2 interiorSrcUv = frac( interiorUv );
float2 interior_tc   = interiorMap( eyeDir, interiorSrcUv, interior_invDepth, interior_backTexSize, 1 );
float3 interiorMap   = tex2D( interiorSampler, interior_tc ).rgb * interior_diffuseOverbright;
finalColor = lerp( interiorMap, finalColor, selfIllumMask.b );

ps.decl:
static const float interior_invDepth          = 1.5;     
static const float interior_backTexSize       = 0.5;     
static const float interior_diffuseOverbright = 18.0f;
float2 interiorMap(float3 eye, float2 tc, float invMapDepth, float backSize, float dilation)
{
// shrink uvs by this much to avoid edge bleed near corners
const float kPadShrink = 0.9;
float3 eyeDir = eye;
eyeDir.z *= invMapDepth;
// Entrance position into the room
float3 pos = float3(tc, 0) * -2 + 1;
pos.z -= 1;
// clip to cube
float3 k = (sign(eyeDir) - pos) / eyeDir;
float t = min(k.x, min(k.y, k.z));
// target is now a point on the unit cube
float3 target = pos + t*eyeDir;
// do the perspective mapping
target.xy *= lerp(dilation, backSize, target.z);
return target.xy*-0.5 + 0.5;
}

ps.main:
// Modulate with diffuse light contributions.
finalColor = finalColor * shColorDiff;
// Add specular contributions.
finalColor += ( finalColor * shColorSpec ) + ( specularColor * spec );

float lightToReflectMagnitude = length( reflectedView - sunSky.mSunDir.xyz );
float hotSpotIntensity        = linearStep1( 0.93f, 0.5f, 1.0f - lightToReflectMagnitude );
// Put in range 0-1
hotSpotIntensity = saturate( hotSpotIntensity * 44.0f );
// Raise to power
hotSpotIntensity = pow( hotSpotIntensity, 8.0f );
float3 hotSpotColour = sunSky.mSunColor.rgb * ( hotSpotIntensity * 9.0f ) * specStrength * shadowModulation;
finalColor += hotSpotColour;

ps.decl:
float linearStep1( float start, float invRange, float value )
{
return saturate( ( value - start ) * invRange );
}

ps.main:
// Tint color is passed through from vertex shader. See notes in shader definition.
float3 baseColor = pow( abs( In.texcoord1.rgb ), float3( 2.2f, 2.2f, 2.2f ) );
float3 worldNormal = In.texcoord0.xyz;
float3 worldViewDirection = normalize(
lerp(
lerp( worldFarCorners[1], worldFarCorners[0], screenUV.y ),
lerp( worldFarCorners[3], worldFarCorners[2], screenUV.y ),
screenUV.x ) ).xyz;
float3 finalColor = DataViewLightingModified( screenUV, worldNormal, worldViewDirection, baseColor, baseColor );
Current.color = float4( finalColor, 1.0f );

ps.decl:
float CalcPhongSpec( float3 lightDir, float3 reflectedNormal, float specE )
{
float nDotR = saturate(dot(reflectedNormal, lightDir));
specE = max(specE, 0.001f);
float spec1 = pow(nDotR, specE);
return spec1;
}
float CalcBlinnPhongSpec( float3 lightDir, float3 viewDir, float3 normal, float specE )
{
float3 halfVector = normalize(lightDir - viewDir);
float nDotH = saturate(dot(normal, halfVector));
specE = max(specE, 0.001f);
float spec = pow(nDotH, specE);
return spec;
}
float CalcBlinnPhongSchlick(float3 lightDir, float3 viewDir, float3 normal, float specE, float specF)
{
float3 halfVector = normalize(lightDir - viewDir);
float nDotH = saturate(dot(normal, halfVector));
specE = max(specE, 0.001f);
float spec = pow(nDotH, specE);
float specNormalizingFactor = (specE + 2) / 8;
float schlick = specF + (1.0f - specF) * exp2(-8.656170 * saturate(dot(lightDir, halfVector))); // 8.656170 == 1/ln(2) * 6
//float schlick = specF + (1 - specF)*pow((1 - dot(halfVector,lightDir)),5);
return spec*specNormalizingFactor*schlick;
}
extern uniform sampler lightScalarSampler : register(s13);
float3 DataViewLightingModified
(
float2 screenUV,
float3 normal,
float3 viewVector,
float3 diffuseColor,
float3 specColor
)
{
float ambientEnabled = 1.0;
float specE = 10;
float reflectance = 0.1;
float3 ambient = diffuseColor * 0.05f;
normal = normalize(normal);
float n_dot_l = saturate((dot(sunSky.mSunDir.xyz, normal) + 1.0f) * 0.5f);
//float n_dot_l = saturate(dot(sunSky.mSunDir.xyz, normal));
float spec = CalcBlinnPhongSchlick(sunSky.mSunDir.xyz, viewVector, normal, specE, reflectance);
float3 diffuse = (diffuseColor * n_dot_l);
float3 specContrib = specColor * spec;
float4 lightScalar = tex2D(lightScalarSampler,screenUV);
float directShadow  = lightScalar.x;
float ambientShadow = lightScalar.y;
float finalShadowTerm = max(directShadow, 0.9f) * max(ambientShadow, 0.2f);
diffuse *= finalShadowTerm;
specContrib *=  finalShadowTerm;
return diffuse + specContrib + ambient * ambientEnabled;
}
float3 DataViewLightingModifiedDirect
(
float3 normal,
float3 viewVector,
float3 diffuseColor,
float3 specColor
)
{
float ambientEnabled = 1.0;
float specE = 10;
float reflectance = 0.1;
float3 ambient = diffuseColor * 0.05f;
normal = normalize(normal);
float n_dot_l = saturate((dot(sunSky.mSunDir.xyz, normal) + 1.0f) * 0.5f);
//float n_dot_l = saturate(dot(sunSky.mSunDir.xyz, normal));
float spec = CalcBlinnPhongSchlick(sunSky.mSunDir.xyz, viewVector, normal, specE, reflectance);
float3 diffuse = (diffuseColor * n_dot_l);
float3 specContrib = specColor * spec;
return diffuse + specContrib + ambient * ambientEnabled;
}

