half  reflectance,
half  specE,
half  specStrength,
inout half3 shColorDiff,
inout half3 shColorSpec,
inout half3 specHighlight
)
{
SceneLighting(
normal, viewVector, glossyStrength, reflectance, specE, specStrength,
shColorDiff, shColorSpec, specHighlight );
}

