float ambientShadow = lightScalar.y;
float finalShadowTerm = max(directShadow, 0.9f) * max(ambientShadow, 0.2f);
diffuse *= finalShadowTerm;
specContrib *=  finalShadowTerm;
return diffuse + specContrib + ambient * ambientEnabled;
}
