//       point.
// tint
float4 tintBase;
float4 specBase;
BuildingPaletteSample( palU, 0.0f, float4( baseTintValues.rgb, 0.0f ), tintBase, specBase );
float4 tintTop;
float4 specTop;
BuildingPaletteSample( palU2, 0.0f, float4( facadeTintValues.rgb, 0.0f ), tintTop, specTop );
