// hw pcf
shadow = tex2Dproj( shadowSampler, shadowPos ).x;
}
else if (style == 7)
{
// weighted, four pcf lookups
float4 offset = off.x * float4(1,1,0,-1) * rttInfoShadow.zwzw;
