dist.x = tex2Dproj(shadowSampler, shadowPos + offset.xyzz).x; //  1 1
dist.y = tex2Dproj(shadowSampler, shadowPos + offset.xwzz).x; //  1-1
dist.z = tex2Dproj(shadowSampler, shadowPos - offset.xwzz).x; // -1 1
