float2 uv                   = In.texcoord0.xy;
float4 color                = tex2D( screenSampler, uv );
color *= 30;
color += 0.5;
color /= 32;
color  = saturate( color );
float2 index0               = float2( color.r, 1-saturate( ( floor( color.b * 32 ) + color.g ) / 32 ) );
float2 index1               = float2( color.r, 1-saturate( ( ceil( color.b * 32 ) + color.g ) / 32 ) );
float3 clut0                = tex2D( stripSampler, index0 ).rgb;
float3 clut1                = tex2D( stripSampler, index1 ).rgb;
Current.color.rgb           = lerp(clut0.rgb,clut1.rgb,frac(color.b*32));
// supposedly doing this will result in better FXAA, but i didn't see much difference.
//Current.color.rgb  = sqrt(Current.color.rgb);
//Current.color.a               = dot(Current.color.rgb, float3(0.299, 0.587, 0.114)); // compute luma;
Current.color.a             = sqrt(dot(Current.color.rgb, float3(0.299, 0.587, 0.114))); // compute luma;

float4 vignetteTint = float4(0.25,0.25,0.25,0.75); //Color (RGB) & Opacity (A) This needs to be external and per CLUT
float4 vignetteTex = tex2D(lensVignetteRadial, In.texcoord0.xy);
vignetteTint.a *= vignetteTex.a;
Current.color.rgb = ((Current.color.rgb * vignetteTint.rgb) * vignetteTint.a) + (Current.color.rgb * (1-vignetteTint.a));

float2 uv                   = In.texcoord0.xy;
float4 color                = tex2D( screenSampler, uv );
float4 clut                 = tex3D( cubeSampler, color.rgb );
Current.color.rgb           = clut.rgb;
Current.color.a             = sqrt(dot(Current.color.rgb, float3(0.299, 0.587, 0.114))); // compute luma;

float2 uv                   = In.texcoord0.xy;
float4 color                = tex2D( screenSampler, uv );
Current.color.rgb           = float3( dot( colorMatrix[0], color.rgb ), dot( colorMatrix[1], color.rgb ), dot( colorMatrix[2], color.rgb ) );
Current.color.a             = sqrt(dot(Current.color.rgb, float3(0.299, 0.587, 0.114))); // compute luma;

// identity texture:
//Current.color       = float4(In.texcoord0.x, 1-frac(In.texcoord0.y * 32.0f), 1-(floor(In.texcoord0.y*32))/32, 1.0f);
Current.color       = tex2D( map, In.texcoord0 );

float t             = cubeInfo[0].x;
float4 diffuse0     = tex2D( map0, In.texcoord0.xy );
float4 diffuse1     = tex2D( map1, In.texcoord0.xy );
Current.color.rgba  = lerp( diffuse0.rgba, diffuse1.rgba, t );

float t                 = cubeInfo[0].x;
float4 colorValues      = tex2D( base, In.texcoord0.xy );
float4 diffuseValues    = tex2D( map, In.texcoord0.xy );
colorValues.rgb         = float3( dot( colorMatrix[0], colorValues.rgb ), dot( colorMatrix[1], colorValues.rgb ), dot( colorMatrix[2], colorValues.rgb ) );
Current.color           = lerp( colorValues, diffuseValues, t );

float4 texh          = In.texcoord0;
float4 texv          = In.texcoord1;
float4 depthValues00 = tex2D( rtDepth, texh.yw );
float4 depthValues0  = tex2D( rtDepth, texh.xw );
float4 depthValues1  = tex2D( rtDepth, texh.zw );
float4 depthValues2  = tex2D( rtDepth, texv.wx );
float4 depthValues3  = tex2D( rtDepth, texv.wz );
// read the control buffer for this pixel and its immediate neighbors
float depth_z_z = unpackDepth( depthValues00.xyz );
float4 depth;
depth.x = unpackDepth( depthValues0.xyz );
depth.y = unpackDepth( depthValues1.xyz );
depth.z = unpackDepth( depthValues2.xyz );
depth.w = unpackDepth( depthValues3.xyz );
float depth_z_z_2 = 2 * depth_z_z;
// sample ID map palette (3 dep reads!, can this be reduced/unpacked ?)
float4 idParameters = float4(.2, .3, 0, 0);
float4 internalLineColor = float4(0,0,0,.4);
float4 externalLineColor = float4(0,0,0,.4);
float2 sensitivity = idParameters.xx * 5000;
float  senseguard  = idParameters.y;
Current.color = internalLineColor;
// TODO: switch line color based on where the contribution to the line comes from (x vs. y)
float4 cmp = float4(0, 0, 0, 0);
if(any(cmp.xy))
{
sensitivity.x = -5000;
Current.color = externalLineColor;
}
if(any(cmp.zw))
{
sensitivity.y = -5000;
Current.color = externalLineColor;
}
//Current.color.a *= 5.0f; // $$$REI TEMP
//sensitivity = -5000; // $$$REI TEMP
float2 detect = make_float2(depth_z_z_2) - depth.xz - depth.yw;
detect *= sensitivity;
detect = max(detect, 0);
float edge = detect.x + detect.y;
float toonResult = saturate(edge - senseguard);
Current.color.a *= toonResult;

