ps.decl:
extern uniform sampler map : register(s0);
static const float tmShoulderStrength  = 0.15;
static const float tmLinearStrength    = 0.50;
static const float tmLinearAngle       = 0.10;
static const float tmToeStrength       = 0.20;
static const float tmToeNumerator      = 0.02;
static const float tmToeDenominator    = 0.30;
/*
static const float tmShoulderStrength  = 0.22;
static const float tmLinearStrength    = 0.30;
static const float tmLinearAngle       = 0.10;
static const float tmToeStrength       = 0.20;
static const float tmToeNumerator      = 0.01;
static const float tmToeDenominator    = 0.30;
*/
static const float tmBaseWhite         = 11.2;
float3 toneMap(float3 inColor)
{
return ((inColor*(tmShoulderStrength*inColor + tmLinearAngle*tmLinearStrength) + tmToeStrength*tmToeNumerator) /
(inColor*(tmShoulderStrength*inColor + tmLinearStrength) + tmToeStrength*tmToeDenominator)) - tmToeNumerator/tmToeDenominator;
}

ps.main:
float3 texColor = tex2D(map, In.texcoord<t0>.xy).rgb;
// hejl vision:
texColor *= sunSky.mSunColor.w;
float3 x = max(float3(0, 0, 0), texColor-0.004);
float3 outColor = (x*(6.2*x+.5))/(x*(6.2*x+1.7)+0.06);
float gamma = userGammaAndFog.mGammaAndFog.x;
// Results of Hejl tonemapping is in sRGB space so all we need to do is apply
// the user requested ramp and post-monitor-gamma-correction, the final image
// will be in the user requested gamma space.
outColor = pow(outColor, make_float3(gamma));
Current.color.rgba = float4(outColor,1);

float3 texColor = tex2D(map, In.texcoord<t0>.xy).rgb;
float gamma = userGammaAndFog.mGammaAndFog.x;
Current.color.rgba = float4(pow(texColor, make_float3(gamma/2.2)),1);

float3 texColor = tex2D(map, In.texcoord<t0>.xy).rgb;
float3 outColor = sqrt(max(texColor-sunSky.mZenith.w,0.0));
Current.color.rgba = float4(outColor,1);

float2 screenUV = In.texcoord<t0>.xy;
float3 texColor = tex2D(colorMap, screenUV).rgb;
float3 bloomColor = tex2D(bloom, screenUV).rgb;

float4 tint = float4(0.7f, 0.3f, 0.8f, 1.0f);
int flareSamples = 12;
float flareOffset = 0.25f;
float flareBlurScale = 0.5f;
float flareThreshold = 2.25f;
float flareIntensity = 0.25f;
bloomColor += postLensFlarePS(screenUV, flareSamples, tint, flareOffset, flareBlurScale, flareThreshold).rgb  * flareIntensity;

ps.decl:
extern uniform sampler bloomSampler : register(s1);
float4 postLensFlarePS (float2 in_vTexCoord, int NumSamples, float4 vTint, float fTexScale, float fBlurScale, float fThreshold)
{
//Flip Screen so flare appears opposite bloom source
float2 vMirrorCoord = float2(1.0f, 1.0f) - in_vTexCoord;
float2 vNormalizedCoord = vMirrorCoord * 2.0f - 1.0f;
vNormalizedCoord *= fTexScale;
float2 screenSize = float2(1680,1050);
float2 vTowardCenter = normalize(-vNormalizedCoord);
float2 fBlurDist = fBlurScale * NumSamples;
float2 vStartPoint = vNormalizedCoord + ((vTowardCenter / screenSize) * fBlurDist);
float2 vStep = -(vTowardCenter / screenSize) * 2 * fBlurDist;
float4 vSum = 0;
float2 vSamplePos = vStartPoint;
float2 vSampleTexCoord = vSamplePos * 0.5f + 0.5f;
for (int i = 0; i < NumSamples; i++)
{
if (vSampleTexCoord.x >= 0 && vSampleTexCoord.x <= 1.0f && vSampleTexCoord.y >=0 && vSampleTexCoord.y <= 1.0f)
{
float4 vSample = tex2D(bloom, vSampleTexCoord);
vSum +=  max(0, vSample - fThreshold) * vTint;
}
vSamplePos += vStep;
vSampleTexCoord = vSamplePos * 0.5f + 0.5f;
}
return vSum / NumSamples;
}

ps.main:
// Proper composite!
float  depthHiRes;
float4 depthLoRes;
float4 depthWeights;
float4 loResCol[4];
// sample depths, compute depth weights
// hires depth
depthHiRes = getNonLinearDepth( depthMap, In.texcoord<t0>.xy );
// lores uv's
float2 uv0 = In.texcoord<t1>.xy;
float2 uv1 = In.texcoord<t1>.zw;
float2 uv2 = In.texcoord<t2>.xy;
float2 uv3 = In.texcoord<t2>.zw;
// lores depths
depthLoRes.x = getNonLinearDepth( depthLowResMap, uv0 );
depthLoRes.y = getNonLinearDepth( depthLowResMap, uv1 );
depthLoRes.z = getNonLinearDepth( depthLowResMap, uv2 );
depthLoRes.w = getNonLinearDepth( depthLowResMap, uv3 );
// lores colours
loResCol[0] = tex2D( effectsLowResMap, uv0 );
loResCol[1] = tex2D( effectsLowResMap, uv1 );
loResCol[2] = tex2D( effectsLowResMap, uv2 );
loResCol[3] = tex2D( effectsLowResMap, uv3 );
// depth difference hires to all lores depths
float4 depthDiff = abs( make_float4(depthHiRes) - depthLoRes.xyzw );
// weight the depth differences (smaller difference => larger weight)
depthWeights = 1.0f / max( depthDiff, kEpsilon );
float  totalWeight = 0;
float4 upsampled   = float4(0, 0, 0, 0);
// get bilinear weights
float4 bilinWeights;
// Calculate bilinear weights
bilinWeights = ( In.texcoord<t0>.xyxy - uv0.xyxy ) * ( renderTargetInfo0.xyxy * 0.5f );
bilinWeights.xy = 1.0f - bilinWeights.xy;
bilinWeights = bilinWeights.xzxz * bilinWeights.yyww;
// Combine the two sets of weights
float4 combinedWeights = depthWeights * bilinWeights;
totalWeight = dot( combinedWeights, float4( 1.0f, 1.0f, 1.0f, 1.0f ) );
combinedWeights /= totalWeight;
// sum lores colour pixels by weight
upsampled = loResCol[0] * combinedWeights.xxxx;
upsampled = loResCol[1] * combinedWeights.yyyy + upsampled;
upsampled = loResCol[2] * combinedWeights.zzzz + upsampled;
upsampled = loResCol[3] * combinedWeights.wwww + upsampled;
Current.color = upsampled;

ps.decl:
float3 mulq(float3 v, float4 q)
{
q *= 1.41421356237; // sqrt(2.0);
return v + cross(q.xyz, cross(q.xyz, v) + q.w * v);
}
float unpackDepth( float3 packeddepth )
{
return dot( packeddepth, float3( 1, 1 / 255.0f, 1 / (255.0*255.0) ) );
}
sampler effectsLowResMap : register(s0);
sampler depthMap         : register(s1);
sampler depthLowResMap   : register(s2);
float getNonLinearDepth( sampler depthMap, float2 uv )
{
float4 depthSample = tex2D( depthMap, uv );
float  depth       = unpackDepth( depthSample.xyz ) * nearFar.y;
return depth;
}
static const float kEpsilon = 0.00000001f;

ps.main:
const float kColorErrFactor = 256.0;
float4 curColor = tex2D(currentColorTexture, In.texcoord0.xy);
float4 oldColor = tex2D(oldColorTexture, In.texcoord0.xy);
float3 colorDiff = oldColor.xyz - curColor.xyz;
float  colorErr  = dot(colorDiff, colorDiff) * kColorErrFactor;
Current.color = float4(curColor.xyz, colorErr);

float2 screenUV = float2(In.texcoord<t0>.xy);
float3 farPoint  = In.texcoord<t1>.xyz;
float3 depthPixels = tex2D(depthTexture, screenUV).xyz;
float unitDepth = (depthPixels.x * 255.0 + depthPixels.y + depthPixels.z / 255.0) / 255.0;  
float3 viewPosition  = worldCameraPosition.xyz;
float3 viewDirection = normalize(farPoint);
float3 worldDistance = make_float3(unitDepth * nearFar.y);
float3 worldPos = viewPosition + farPoint * unitDepth;
float4x4 prevWorldToClip = float4x4(
motionBlurInfo.mPrevWorldToClipX,
motionBlurInfo.mPrevWorldToClipY,
motionBlurInfo.mPrevWorldToClipZ,
motionBlurInfo.mPrevWorldToClipW);
float4 tmp = mul(float4(worldPos, 1), prevWorldToClip);
float3 prevClipPos = tmp.xyz / tmp.w;
float2 prevUV = prevClipPos.xy * 0.5 + 0.5;
prevUV.y = saturate(1.0 - prevUV.y);
float2 uvStep = kBlurDistance * (prevUV - screenUV);
